package com.jobpilot.dashboard;import com.jobpilot.application.*;import com.jobpilot.config.CurrentUserService;import com.jobpilot.job.JobOfferRepository;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/dashboard")public class DashboardController{private final CurrentUserService current;private final JobOfferRepository jobs;private final ApplicationRepository apps;public DashboardController(CurrentUserService c,JobOfferRepository j,ApplicationRepository a){current=c;jobs=j;apps=a;}public record Dashboard(long jobs,long applications,long interviews,long offers,long rejected){}@GetMapping Dashboard get(){Long id=current.get().getId();return new Dashboard(jobs.countByUserId(id),apps.countByUserId(id),apps.countByUserIdAndStatus(id,ApplicationStatus.INTERVIEW),apps.countByUserIdAndStatus(id,ApplicationStatus.OFFER),apps.countByUserIdAndStatus(id,ApplicationStatus.REJECTED));}}
